export default {
  id: 'math-role',
  name: 'Math Role',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'role',
      role: {
        id: 'math-check',
        name: 'Math Check',
        description: 'Reads a user-provided arithmetic expression and reports only the result.',
        systemPrompt:
          'You are a math checker. Read the arithmetic expression given by the user, evaluate it, and report ONLY the numeric result. Do not add explanations, steps, or extra text. Output just the result value.',
        tools: 'readonly'
      }
    });
  }
};
